import React, { useState } from "react";
import "./TitleCard.css";
import imgFold from "../img/Fold (1).png"
import TaskCard from "../TaskCard/TaskCard";

const TitleCard = (prop) => {

    const [targ, setTarg] = useState(false);

    const handleFold = () => {
        if (targ) 
            setTarg(false);
        else 
            setTarg(true);
    }

    const listSubtask = (subtasks) => {
        if(!!subtasks)
        return(subtasks.map(subtask =>(
            <TaskCard prop={subtask}/>)))
        else 
        return(<h4>Загрузка...</h4>)
    }

    return(
        <div className="ComponentCardSB">
            <div className="TitleProgectCardSB">
                <h3 className="NameProjectCardSB">{prop.nameProject}</h3>
                <div className="ComponentButtonCardSB">
                    <button className="ButtonFoldCardSB" onClick={handleFold}><img className="ImgFoldCardSB" src={imgFold}></img></button>
                </div>
            </div>

            {targ && <div className="listTaskCardSB">
                    {listSubtask(prop.Tasks)}
                </div>
            }
        </div>
    )
}

export default TitleCard;
